def max3(a, b, c):
    if a >= b and a >= c:
        return a
    elif b >= a and b >= c:
        return b
    else:
        return c

# Example usage:
print(max3(10, 20, 30))  # Output: 30
print(max3(-5, 5, 0))    # Output: 5
```

